// ============================================================
// Nœud : "Normaliser la requête"   (Mode : Run Once for Each Item)
// Reçoit soit une ligne utilisateur (Schedule), soit un appel Webhook.
// Produit une requête propre et validée pour la suite du pipeline.
// ============================================================
const STYLES = ['casual', 'chic', 'sport', 'business', 'streetwear', 'boheme'];
const OCCASIONS = ['quotidien', 'travail', 'sortie', 'sport', 'rendez-vous', 'week-end', 'voyage'];
const SIMULATIONS = {
  pluie_froide: { tmin: 4, tmax: 9, feels_min: 1, feels_max: 6, precip_prob: 90, precip_mm: 8, wind_kmh: 30, uv: 1, code: 63 },
  canicule:     { tmin: 24, tmax: 36, feels_min: 25, feels_max: 38, precip_prob: 0, precip_mm: 0, wind_kmh: 8, uv: 9, code: 0 },
  neige:        { tmin: -5, tmax: 1, feels_min: -10, feels_max: -2, precip_prob: 80, precip_mm: 4, wind_kmh: 20, uv: 1, code: 73 },
  vent_fort:    { tmin: 12, tmax: 17, feels_min: 8, feels_max: 14, precip_prob: 20, precip_mm: 0, wind_kmh: 55, uv: 3, code: 3 },
  printemps:    { tmin: 11, tmax: 20, feels_min: 10, feels_max: 20, precip_prob: 10, precip_mm: 0, wind_kmh: 12, uv: 5, code: 1 },
};

const isWebhook = $json.headers !== undefined && $json.body !== undefined;
let b = isWebhook ? $json.body : $json;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};

const warnings = [];
const clean = (v) => (typeof v === 'string' && v.trim() ? v.trim().toLowerCase() : null);

function parisDate(offsetDays) {
  const d = new Date(Date.now() + offsetDays * 86400000);
  return d.toLocaleDateString('sv-SE', { timeZone: 'Europe/Paris' }); // => YYYY-MM-DD
}

let style = clean(b.style);
if (style && !STYLES.includes(style)) {
  warnings.push(`Style inconnu « ${b.style} » : le style du profil est utilisé.`);
  style = null;
}
let occasion = clean(b.occasion);
if (occasion && !OCCASIONS.includes(occasion)) {
  warnings.push(`Occasion inconnue « ${b.occasion} » : l'occasion par défaut est utilisée.`);
  occasion = null;
}

const dayOffset = [0, 1].includes(Number(b.day_offset)) ? Number(b.day_offset) : 0;

let source = 'schedule';
if (isWebhook) source = ['eval', 'eval_dry'].includes(b.source) ? b.source : 'webhook';

// Mode simulation : météo forcée (démo live ou jeu de test d'évaluation)
let weatherOverride = null;
if (b.weather_override && typeof b.weather_override === 'object') weatherOverride = b.weather_override;
else if (typeof b.simulate === 'string' && SIMULATIONS[b.simulate]) weatherOverride = { ...SIMULATIONS[b.simulate], label: b.simulate };
// Une simulation lancée depuis l'appli ne doit pas polluer l'historique réel
if (weatherOverride && source === 'webhook') {
  source = 'eval_dry';
  warnings.push('Mode simulation : cette tenue n’est pas enregistrée dans ton historique.');
}

const validDate = typeof b.outfit_date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(b.outfit_date);
const outfitDate = validDate && source.startsWith('eval') ? b.outfit_date : parisDate(dayOffset);

return {
  json: {
    source,
    user_id: parseInt(b.user_id ?? 1, 10) || 1,
    city: typeof b.city === 'string' && b.city.trim() ? b.city.trim().slice(0, 80) : null,
    style,
    occasion,
    day_offset: dayOffset,
    outfit_date: outfitDate,
    format: b.format === 'json' ? 'json' : 'html',
    model: typeof b.model === 'string' && b.model.includes('/') ? b.model : null,
    weather_override: weatherOverride,
    base_url: isWebhook && $json.webhookUrl ? String($json.webhookUrl).replace(/[^/]*$/, '') : '',
    warnings,
  },
};

// ============================================================
// Nœud : "Résoudre la localisation"   (Mode : Run Once for Each Item)
// Combine le contexte BDD + le résultat du géocodage Open-Meteo.
// Si la ville est introuvable -> repli sur la ville du profil (pas de crash).
// ============================================================
const base = $('Charger profil & garde-robe').item.json; // { req, ctx }
const geo = $json || {};
const req = base.req;
const ctx = base.ctx;
const warnings = [...(req.warnings || [])];

if (!ctx || !ctx.user) {
  return { json: { req, ctx: null, warnings, fatal: `Utilisateur n°${req.user_id} introuvable.` } };
}
if (!Array.isArray(ctx.wardrobe) || ctx.wardrobe.length === 0) {
  return { json: { req, ctx, warnings, fatal: 'Ta garde-robe est vide (ou tout est au linge sale) : ajoute des pièces disponibles.' } };
}

const r = Array.isArray(geo.results) && geo.results.length ? geo.results[0] : null;
let location;
if (r) {
  location = { name: r.name, country: r.country || null, lat: r.latitude, lon: r.longitude, source: 'geocoding' };
} else {
  if (req.city) warnings.push(`Ville « ${req.city} » introuvable : ${ctx.user.city} est utilisée.`);
  if (geo.error) warnings.push('Service de géocodage indisponible : coordonnées du profil utilisées.');
  location = { name: ctx.user.city, country: null, lat: ctx.user.latitude, lon: ctx.user.longitude, source: 'profil' };
}

return { json: { req, ctx, location, warnings, fatal: null } };

// ============================================================
// Nœud : "Analyser la météo"   (Mode : Run Once for Each Item)
// Transforme la réponse Open-Meteo en "features" exploitables :
// ressenti effectif (ajusté à la frilosité), bande thermique,
// pluie / neige / vent / UV, écart matin-soir, contraintes de tenue.
// ============================================================
const base = $('Résoudre la localisation').item.json; // { req, ctx, location, warnings }
const api = $json || {};
const { req, ctx, location } = base;
const warnings = [...(base.warnings || [])];
if (base.fatal) return { json: base }; // erreur déjà détectée en amont : on la transmet

const WMO = {
  0: 'Ciel dégagé', 1: 'Plutôt ensoleillé', 2: 'Partiellement nuageux', 3: 'Couvert',
  45: 'Brouillard', 48: 'Brouillard givrant', 51: 'Bruine légère', 53: 'Bruine', 55: 'Bruine dense',
  56: 'Bruine verglaçante', 57: 'Bruine verglaçante', 61: 'Pluie faible', 63: 'Pluie modérée',
  65: 'Pluie forte', 66: 'Pluie verglaçante', 67: 'Pluie verglaçante forte', 71: 'Neige faible',
  73: 'Neige modérée', 75: 'Neige forte', 77: 'Grains de neige', 80: 'Averses faibles',
  81: 'Averses', 82: 'Averses violentes', 85: 'Averses de neige', 86: 'Fortes averses de neige',
  95: 'Orage', 96: 'Orage avec grêle', 99: 'Orage violent avec grêle',
};
const round1 = (x) => Math.round(x * 10) / 10;

let w; // météo brute du jour cible
if (req.weather_override) {
  const o = req.weather_override;
  const fmin = o.feels_min ?? o.tmin, fmax = o.feels_max ?? o.tmax;
  w = {
    tmin: o.tmin, tmax: o.tmax, feels_min: fmin, feels_max: fmax,
    precip_prob: o.precip_prob ?? 0, precip_mm: o.precip_mm ?? 0,
    wind_kmh: o.wind_kmh ?? 10, uv: o.uv ?? 3, code: o.code ?? 2,
    morning: o.morning ?? fmin + (fmax - fmin) * 0.2,
    afternoon: o.afternoon ?? fmax,
    evening: o.evening ?? fmin + (fmax - fmin) * 0.5,
    simulated: true, simulation_label: o.label || 'scénario de test',
  };
} else {
  if (!api.daily || !Array.isArray(api.daily.time)) {
    return { json: { ...base, warnings, fatal: 'Service météo indisponible pour le moment, réessaie dans quelques minutes.' } };
  }
  const d = api.daily;
  let i = d.time.indexOf(req.outfit_date);
  if (i < 0) { i = 0; warnings.push('Date hors prévisions : météo du jour utilisée.'); }
  const hourAt = (h, field) => {
    if (!api.hourly || !api.hourly.time) return null;
    const k = api.hourly.time.indexOf(`${d.time[i]}T${String(h).padStart(2, '0')}:00`);
    return k >= 0 ? api.hourly[field][k] : null;
  };
  w = {
    tmin: d.temperature_2m_min[i], tmax: d.temperature_2m_max[i],
    feels_min: d.apparent_temperature_min[i], feels_max: d.apparent_temperature_max[i],
    precip_prob: d.precipitation_probability_max?.[i] ?? 0,
    precip_mm: d.precipitation_sum?.[i] ?? 0,
    wind_kmh: d.wind_speed_10m_max?.[i] ?? 0,
    uv: d.uv_index_max?.[i] ?? 0,
    code: d.weather_code[i],
    morning: hourAt(8, 'apparent_temperature'),
    afternoon: hourAt(14, 'apparent_temperature'),
    evening: hourAt(19, 'apparent_temperature'),
    simulated: false,
  };
  if (w.morning === null) w.morning = w.feels_min;
  if (w.afternoon === null) w.afternoon = w.feels_max;
  if (w.evening === null) w.evening = (w.feels_min + w.feels_max) / 2;
}

// --- Features -------------------------------------------------------------
const ADJ = { frileux: -3, normal: 0, chaud: 2 };
const adj = ADJ[ctx.user.cold_sensitivity] ?? 0;
// ressenti "journée" pondéré : on est surtout dehors le matin et l'après-midi
const feelsDay = 0.4 * w.morning + 0.4 * w.afternoon + 0.2 * w.evening;
const effective = round1(feelsDay + adj);

let band;
if (effective < 5) band = 'very_cold';
else if (effective < 11) band = 'cold';
else if (effective < 16) band = 'cool';
else if (effective < 21) band = 'mild';
else if (effective < 26) band = 'warm';
else band = 'hot';

const code = Number(w.code);
const snow = [71, 73, 75, 77, 85, 86].includes(code);
const storm = code >= 95;
const rain = !snow && (w.precip_prob >= 50 || w.precip_mm >= 1 || (code >= 51 && code <= 67) || (code >= 80 && code <= 82) || storm);
const heavyRain = rain && (w.precip_mm >= 5 || [65, 67, 82].includes(code) || storm);
const windy = w.wind_kmh >= 35;
const uvHigh = w.uv >= 6;
const sunny = code <= 1;
const swing = round1(Math.max(w.morning, w.afternoon, w.evening) - Math.min(w.morning, w.afternoon, w.evening));

// Plage cible de chaleur cumulée (haut + couche intermédiaire + manteau)
const TARGET = { very_cold: [9, 14], cold: [6, 11], cool: [4, 8], mild: [2, 5], warm: [1, 3], hot: [0, 2] };
const BOTTOM = { very_cold: [2, 5], cold: [2, 5], cool: [1, 5], mild: [1, 4], warm: [0, 2], hot: [0, 1] };
const bandIdx = ['very_cold', 'cold', 'cool', 'mild', 'warm', 'hot'].indexOf(band);

const requirements = {
  layer_warmth_target: TARGET[band],
  bottom_warmth_range: BOTTOM[band],
  mid_layer_required: bandIdx <= 1,
  outerwear_required: bandIdx <= 2 || snow || (windy && bandIdx <= 3),
  rain_protection_required: rain || snow,
  waterproof_shoes_preferred: heavyRain || snow,
  layering_advised: swing >= 8,
};

const BAND_FR = { very_cold: 'très froid', cold: 'froid', cool: 'frais', mild: 'doux', warm: 'chaud', hot: 'très chaud' };
const flags = [];
if (rain) flags.push(heavyRain ? 'fortes pluies' : 'pluie probable');
if (snow) flags.push('neige');
if (storm) flags.push('orage');
if (windy) flags.push('vent fort');
if (uvHigh) flags.push('UV élevés');
if (requirements.layering_advised) flags.push(`écart de ${swing}°C dans la journée`);

const weather = {
  date: req.outfit_date,
  city: location.name,
  description: WMO[code] || 'Conditions variables',
  code,
  tmin: round1(w.tmin), tmax: round1(w.tmax),
  feels_min: round1(w.feels_min), feels_max: round1(w.feels_max),
  feels_morning: round1(w.morning), feels_afternoon: round1(w.afternoon), feels_evening: round1(w.evening),
  effective_feel: effective,
  cold_adjustment: adj,
  precip_prob: w.precip_prob, precip_mm: round1(w.precip_mm),
  wind_kmh: round1(w.wind_kmh), uv: round1(w.uv),
  rain, heavy_rain: heavyRain, snow, storm, windy, uv_high: uvHigh, sunny, swing,
  band, band_fr: BAND_FR[band], flags,
  simulated: !!w.simulated, simulation_label: w.simulation_label || null,
  requirements,
  summary: `${WMO[code] || 'Temps variable'}, ${round1(w.tmin)}→${round1(w.tmax)}°C `
    + `(ressenti ${round1(w.morning)}°C le matin, ${round1(w.afternoon)}°C l'après-midi, ${round1(w.evening)}°C le soir), `
    + `pluie ${w.precip_prob}% (${round1(w.precip_mm)} mm), vent ${round1(w.wind_kmh)} km/h, UV ${round1(w.uv)}.`,
};

return { json: { req, ctx, location, weather, warnings, fatal: null } };

// ============================================================
// Nœud : "Pré-filtrer & construire le prompt"   (Mode : Run Once for Each Item)
// 1) Filtres durs : météo (chaleur, pluie), anti-répétition (cooldown),
//    pièces déjà proposées aujourd'hui.
// 2) Score de pertinence : style, formalité, rotation, notes utilisateur.
// 3) On garde le top N par catégorie -> prompt court, LLM "ancré" (pas d'invention).
// ============================================================
const MODEL_DEFAULT = 'openai/gpt-4o-mini'; // modèle gratuit build.nvidia.com

const { req, ctx, location, weather } = $json;
const warnings = [...($json.warnings || [])];
const user = ctx.user;
const STYLE = req.style || user.preferred_style;
const OCCASION = req.occasion || user.default_occasion;
const band = weather.band;
const R = weather.requirements;
const BANDS = ['very_cold', 'cold', 'cool', 'mild', 'warm', 'hot'];
const bi = BANDS.indexOf(band);

const OCC_FORMALITY = { quotidien: 2, travail: 4, sortie: 3, sport: 1, 'rendez-vous': 3.5, 'week-end': 2, voyage: 2 };
const targetFormality = OCC_FORMALITY[OCCASION] ?? 2;
const COOLDOWN = { base_top: 4, bottom: 2, mid_layer: 2, outerwear: 0, shoes: 0, accessory: 0 }; // en jours
const KEEP = { base_top: 6, mid_layer: 5, bottom: 6, outerwear: 5, shoes: 5, accessory: 8 };
const IDEAL = { // chaleur idéale par catégorie selon la bande
  base_top:  { very_cold: 3, cold: 2, cool: 2, mild: 1, warm: 1, hot: 0 },
  mid_layer: { very_cold: 4, cold: 3, cool: 2, mild: 1, warm: 1, hot: 0 },
  outerwear: { very_cold: 5, cold: 4, cool: 2, mild: 1, warm: 1, hot: 0 },
  shoes:     { very_cold: 3, cold: 3, cool: 2, mild: 1, warm: 1, hot: 0 },
};
const proposedToday = new Set(ctx.already_proposed_today || []);

// ---------- Filtres durs ----------------------------------------------------
function hardReject(it, useCooldown) {
  const c = it.category, wv = it.warmth, sub = it.subcategory;
  if (['base_top', 'bottom', 'mid_layer'].includes(c) && proposedToday.has(it.id)) return 'déjà proposé aujourd’hui';
  if (useCooldown && it.days_since_worn !== null && it.days_since_worn < COOLDOWN[c]) return 'porté trop récemment';
  if (c === 'base_top' && ((band === 'hot' && wv >= 3) || (bi <= 1 && wv === 0))) return 'chaleur inadaptée';
  if (c === 'mid_layer' && bi >= 4 && wv >= 3) return 'trop chaud';
  if (c === 'bottom' && (wv < R.bottom_warmth_range[0] || wv > R.bottom_warmth_range[1])) return 'chaleur inadaptée';
  if (c === 'outerwear') {
    if (band === 'hot' && wv >= 2) return 'trop chaud';
    if (band === 'warm' && wv >= 4) return 'trop chaud';
    if (band === 'mild' && wv >= 4 && !weather.snow) return 'trop chaud';
    if (band === 'cool' && wv >= 5 && !weather.snow) return 'trop chaud';
    if (band === 'very_cold' && wv < 3) return 'pas assez chaud';
    if (band === 'cold' && wv < 2) return 'pas assez chaud';
  }
  if (c === 'shoes') {
    if ((bi <= 2 || weather.rain || weather.snow) && wv === 0) return 'chaussures ouvertes inadaptées';
    if (band === 'hot' && wv >= 3 && !weather.rain) return 'trop chaud';
    if (weather.snow && !it.waterproof) return 'pas imperméable (neige)';
  }
  if (c === 'accessory') {
    if (['bonnet', 'gants'].includes(sub) && bi >= 3) return 'inutile par cette chaleur';
    if (sub === 'echarpe' && bi >= 4) return 'inutile par cette chaleur';
    if (sub === 'chapeau' && (weather.rain || bi <= 2)) return 'inadapté';
  }
  return null;
}

// ---------- Score de pertinence -------------------------------------------
function accessoryRelevance(it) {
  const s = it.subcategory;
  if (s === 'parapluie') return R.rain_protection_required ? 6 : -3;
  if (s === 'lunettes_soleil') return (weather.uv_high || (weather.sunny && bi >= 3)) ? 4 : -1;
  if (s === 'casquette' || s === 'chapeau') return weather.uv_high && bi >= 3 ? 3 : -1;
  if (s === 'bonnet' || s === 'gants') return bi === 0 ? 4 : bi === 1 ? 1 : -2;
  if (s === 'echarpe') return bi <= 1 ? 3 : (bi === 2 || weather.windy) ? 1 : -2;
  return 0; // ceinture, montre, sac, foulard : neutres
}

function score(it) {
  let s = 0;
  const styles = it.styles || [];
  if (styles.includes(STYLE)) s += 4;
  else if (styles.includes('casual')) s += 1;
  else s -= 2;
  if (OCCASION === 'sport' && styles.includes('sport')) s += 3;
  s -= 1.2 * Math.abs(it.formality - targetFormality);
  // rotation : on favorise ce qui n'a pas été porté depuis longtemps
  if (it.days_since_worn === null) s += 1.5;
  else s += Math.min(it.days_since_worn, 14) * 0.15;
  s -= 0.8 * (it.wear_count_14d || 0);
  // apprentissage à partir des notes de l'utilisateur
  if (it.avg_rating !== null && it.avg_rating !== undefined) s += (Number(it.avg_rating) - 3) * 1.2;
  if (IDEAL[it.category]) s -= 0.7 * Math.abs(it.warmth - IDEAL[it.category][band]);
  if (R.rain_protection_required && it.waterproof && ['outerwear', 'shoes'].includes(it.category)) s += 3;
  if (it.category === 'accessory') s += accessoryRelevance(it);
  return Math.round(s * 100) / 100;
}

// ---------- Sélection des candidats ---------------------------------------
const CATS = ['base_top', 'mid_layer', 'bottom', 'outerwear', 'shoes', 'accessory'];
const candidates = {};
const excludedStats = {};
for (const cat of CATS) {
  const pool = ctx.wardrobe.filter((it) => it.category === cat);
  let kept = pool.filter((it) => {
    const why = hardReject(it, true);
    if (why) excludedStats[why] = (excludedStats[why] || 0) + 1;
    return !why;
  });
  if (kept.length === 0 && pool.length > 0 && ['base_top', 'bottom', 'shoes'].includes(cat)) {
    kept = pool.filter((it) => !hardReject(it, false));
    if (kept.length === 0) kept = pool; // dernier recours : on garde tout plutôt que d'échouer
    warnings.push(`Peu de choix en « ${cat} » : l'anti-répétition a été assouplie.`);
  }
  candidates[cat] = kept
    .map((it) => ({ ...it, score: score(it) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, KEEP[cat]);
}
if (R.mid_layer_required && candidates.mid_layer.length === 0) R.mid_layer_required = false;
if (R.outerwear_required && candidates.outerwear.length === 0) R.outerwear_required = false;

// ---------- Historique pour l'anti-répétition -------------------------------
const nameById = Object.fromEntries(ctx.wardrobe.map((it) => [it.id, it.name]));
const recent = (ctx.recent_outfits || []).slice(0, 7);
const historyLines = recent.length
  ? recent.map((o) => `- ${o.date} : ${(o.item_ids || []).map((id) => nameById[id] || `#${id}`).join(', ')}`
      + ` (haut+bas ${o.combo_key})${o.rating ? ` — note ${o.rating}/5` : ''}`).join('\n')
  : '- (aucune tenue récente)';
const forbiddenCombos = [...new Set((ctx.recent_outfits || []).map((o) => o.combo_key).filter(Boolean))];

const fmt = (it) => {
  const worn = it.days_since_worn === null ? 'jamais porté récemment' : `porté il y a ${it.days_since_worn} j`;
  return `  #${it.id} ${it.name} | ${it.color} | chaleur ${it.warmth}${it.waterproof ? ' | imperméable' : ''}`
    + ` | styles ${it.styles.join('/')} | formalité ${it.formality} | ${worn}`;
};
const catBlock = (cat, label) => `${label}:\n${candidates[cat].length ? candidates[cat].map(fmt).join('\n') : '  (aucune pièce)'}`;

// ---------- Prompts ---------------------------------------------------------
const systemPrompt = `Tu es « Météo-Dressing », un styliste personnel expert, pragmatique et bienveillant.
Ta mission : composer LA tenue du jour à partir d'une garde-robe réelle, selon la météo, le style et l'occasion.

RÈGLES STRICTES
1. Choisis UNIQUEMENT des pièces de la liste fournie, désignées par leur numéro (id). N'invente jamais de pièce.
2. Catégories : base_top (1 obligatoire), bottom (1 obligatoire), shoes (1 obligatoire), mid_layer (0 ou 1, obligatoire si indiqué), outerwear (0 ou 1, obligatoire si indiqué), accessories (0 à 3).
3. Confort thermique : la somme des chaleurs base_top + mid_layer + outerwear doit rester dans la plage cible indiquée.
4. Pluie ou neige : prévois une protection (outerwear imperméable ou parapluie).
5. Anti-répétition : ne reprends jamais une combinaison haut+bas de l'historique ; privilégie les pièces peu portées récemment.
6. Harmonie : 3 couleurs dominantes maximum dont au moins une neutre ; respecte le style et la formalité de l'occasion.
7. Écris en français, en tutoyant, avec un ton chaleureux et concret.

FORMAT DE SORTIE
Réponds UNIQUEMENT avec un objet JSON valide, sans texte autour et sans balises Markdown :
{
  "outfit": {"base_top": <id>, "mid_layer": <id ou null>, "bottom": <id>, "outerwear": <id ou null>, "shoes": <id>, "accessories": [<id>, ...]},
  "title": "<nom court et accrocheur de la tenue, 6 mots maximum>",
  "advice": "<conseil personnalisé de 40 à 80 mots qui justifie les choix par la météo et le style>",
  "tips": ["<astuce pratique courte>", "<astuce pratique courte>"],
  "palette": ["<couleur>", "<couleur>", "<couleur>"]
}`;

const T = R.layer_warmth_target;
const userPrompt = `CONTEXTE DU JOUR
- Date : ${weather.date} — ${weather.city}${weather.simulated ? ' (météo simulée)' : ''}
- Météo : ${weather.summary}
- Ressenti retenu : ${weather.effective_feel}°C => temps ${weather.band_fr}${weather.flags.length ? ' ; ' + weather.flags.join(', ') : ''}

PROFIL
- Prénom : ${user.name} | style souhaité : ${STYLE} | occasion : ${OCCASION} | sensibilité au froid : ${user.cold_sensitivity}

CONTRAINTES
- Plage cible de chaleur (base_top + mid_layer + outerwear) : entre ${T[0]} et ${T[1]}
- mid_layer : ${R.mid_layer_required ? 'OBLIGATOIRE' : 'optionnel'} | outerwear : ${R.outerwear_required ? 'OBLIGATOIRE' : 'optionnel'}
- Protection pluie/neige : ${R.rain_protection_required ? 'OBLIGATOIRE' : 'non nécessaire'}${R.layering_advised ? '\n- Grand écart de température : privilégie des couches faciles à retirer' : ''}
- Combinaisons haut+bas interdites (format idHaut-idBas) : ${forbiddenCombos.length ? forbiddenCombos.join(', ') : 'aucune'}

HISTORIQUE RÉCENT (à ne pas répéter)
${historyLines}

PIÈCES DISPONIBLES (déjà filtrées pour la météo)
${catBlock('base_top', 'base_top')}
${catBlock('mid_layer', 'mid_layer')}
${catBlock('bottom', 'bottom')}
${catBlock('outerwear', 'outerwear')}
${catBlock('shoes', 'shoes')}
${catBlock('accessory', 'accessories')}

Compose la tenue et réponds avec le JSON demandé.`;

const model = req.model || MODEL_DEFAULT;
return {
  json: {
    req, ctx: { user, recent_outfits: ctx.recent_outfits, already_proposed_today: ctx.already_proposed_today },
    location, weather, warnings,
    style: STYLE, occasion: OCCASION,
    candidates, forbidden_combos: forbiddenCombos, excluded_stats: excludedStats,
    t0: Date.now(),
    llm_request: {
      model,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
      temperature: 0.5,
      top_p: 0.9,
      max_tokens: 800,
      stream: false,
      response_format: { type: 'json_object' },
    },
  },
};

// ============================================================
// Nœud : "Valider & évaluer la tenue"   (Mode : Run Once for Each Item)
// - Parse la réponse du LLM (tolère ```json, <think>, texte parasite)
// - 8 contrôles automatiques = évaluation de CHAQUE sortie du LLM
// - Réparation légère (parapluie oublié) ou repli déterministe si la sortie
//   est inutilisable : le pipeline ne plante jamais.
// ============================================================
const base = $('Pré-filtrer & construire le prompt').item.json;
const resp = $json || {};
const { req, weather, candidates, style: STYLE } = base;
const R = weather.requirements;
const warnings = [...(base.warnings || [])];
const latency = Date.now() - (base.t0 || Date.now());

// ---------- 1. Parsing robuste ---------------------------------------------
let raw = '';
let apiError = null;
let body = resp;
if (typeof body.data === 'string') { try { body = JSON.parse(body.data); } catch (e) { raw = body.data; } }
if (resp.error) apiError = typeof resp.error === 'string' ? resp.error : (resp.error.message || JSON.stringify(resp.error));
else if (!raw) {
  const content = body?.choices?.[0]?.message?.content;
  raw = Array.isArray(content) ? content.map((c) => c.text || '').join('') : (content ?? '');
  if (!raw && body?.choices === undefined) apiError = 'Réponse inattendue du fournisseur LLM : ' + JSON.stringify(body).slice(0, 300);
}

function parseLLM(text) {
  if (!text || typeof text !== 'string') return null;
  let t = text.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/```(?:json)?/gi, '').trim();
  const start = t.indexOf('{'), end = t.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try { return JSON.parse(t.slice(start, end + 1)); } catch (e) { return null; }
}
const parsed = parseLLM(raw);

// ---------- 2. Contrôles ---------------------------------------------------
const byCat = {};
for (const [cat, list] of Object.entries(candidates)) byCat[cat] = new Map(list.map((it) => [it.id, it]));
// accepte 10, "10", "#10", "#10 Chemise…", {"id":10,...}
const toId = (v) => {
  if (v === null || v === undefined || v === '' || v === 'null') return null;
  if (typeof v === 'object') return toId(v.id ?? v.item_id ?? v.ID ?? null);
  const m = String(v).match(/\d+/);
  return m ? parseInt(m[0], 10) : null;
};
const anyCategoryOf = (id) => {
  for (const [cat, map] of Object.entries(byCat)) if (map.has(id)) return cat;
  return null;
};
const repairs = [];
function normalizeOutfit(o) {
  o = o || {};
  const acc = o.accessories ?? o.accessory ?? [];
  const out = {
    base_top: toId(o.base_top ?? o.top), mid_layer: toId(o.mid_layer), bottom: toId(o.bottom),
    outerwear: toId(o.outerwear), shoes: toId(o.shoes),
    accessories: (Array.isArray(acc) ? acc : [acc]).map(toId).filter((x) => x !== null),
  };
  // pièce existante mais rangée dans la mauvaise catégorie -> on la remet à sa place
  for (const cat of ['base_top', 'mid_layer', 'bottom', 'outerwear', 'shoes']) {
    const id = out[cat];
    if (id === null || byCat[cat]?.has(id)) continue;
    const real = anyCategoryOf(id);
    if (real && real !== 'accessory' && out[real] === null) { out[real] = id; out[cat] = null; repairs.push(`catégorie corrigée pour #${id}`); }
    else if (real === 'accessory') { out.accessories.push(id); out[cat] = null; }
  }
  return out;
}
const itemOf = (cat, id) => (id === null ? null : byCat[cat === 'accessories' ? 'accessory' : cat]?.get(id) || null);
const comboKey = (o) => `${o.base_top}-${o.bottom}`;
const layerWarmth = (o) => ['base_top', 'mid_layer', 'outerwear']
  .reduce((s, c) => s + (itemOf(c, o[c])?.warmth || 0), 0);

function runChecks(o, text) {
  const c = {};
  c.json_valid = !!parsed;
  const singles = ['base_top', 'mid_layer', 'bottom', 'outerwear', 'shoes'];
  c.ids_valid = singles.every((cat) => o[cat] === null || !!itemOf(cat, o[cat]))
    && o.accessories.every((id) => !!itemOf('accessories', id));
  c.required_present = !!(o.base_top && o.bottom && o.shoes
    && (!R.mid_layer_required || o.mid_layer) && (!R.outerwear_required || o.outerwear));
  const lw = layerWarmth(o);
  c.thermal_ok = lw >= R.layer_warmth_target[0] && lw <= R.layer_warmth_target[1];
  const outer = itemOf('outerwear', o.outerwear);
  const hasUmbrella = o.accessories.some((id) => itemOf('accessories', id)?.subcategory === 'parapluie');
  c.rain_ok = !R.rain_protection_required || (outer && outer.waterproof) || hasUmbrella;
  const core = [itemOf('base_top', o.base_top), itemOf('bottom', o.bottom), itemOf('shoes', o.shoes),
    itemOf('outerwear', o.outerwear) || itemOf('mid_layer', o.mid_layer)].filter(Boolean);
  c.style_ok = core.filter((it) => (it.styles || []).includes(STYLE)).length >= 2;
  c.no_repeat = !base.forbidden_combos.includes(comboKey(o));
  const words = (text || '').trim().split(/\s+/).filter(Boolean).length;
  c.advice_ok = words >= 25 && words <= 120;
  return c;
}

let outfit = normalizeOutfit(parsed?.outfit);
const llmChecks = runChecks(outfit, parsed?.advice);
const passed = Object.values(llmChecks).filter(Boolean).length;
const ruleScore = Math.round((passed / Object.keys(llmChecks).length) * 1000) / 1000;

// ---------- 3. Repli déterministe si la sortie est inutilisable -----------
function bestDeterministic() {
  const top = (cat, n) => (candidates[cat] || []).slice(0, n);
  const opt = (cat, required, n) => (required ? top(cat, n) : [null, ...top(cat, n)]);
  let best = null;
  for (const t of top('base_top', 3)) for (const b of top('bottom', 3))
  for (const m of opt('mid_layer', R.mid_layer_required, 3))
  for (const ow of opt('outerwear', R.outerwear_required, 3)) for (const s of top('shoes', 2)) {
    const o = { base_top: t.id, bottom: b.id, mid_layer: m ? m.id : null, outerwear: ow ? ow.id : null, shoes: s.id, accessories: [] };
    const lw = (t.warmth) + (m ? m.warmth : 0) + (ow ? ow.warmth : 0);
    let sc = t.score + b.score + s.score;
    // couches : on ajoute leur score si obligatoires, sinon on préfère la sobriété
    for (const [layer, req] of [[m, R.mid_layer_required], [ow, R.outerwear_required]]) {
      if (!layer) continue;
      if (req) sc += layer.score;
      else sc += (R.rain_protection_required && layer.waterproof) ? 2 : -1.5;
    }
    if (lw < R.layer_warmth_target[0] || lw > R.layer_warmth_target[1]) sc -= 20;
    sc -= 0.5 * Math.abs(lw - (R.layer_warmth_target[0] + R.layer_warmth_target[1]) / 2);
    if (base.forbidden_combos.includes(comboKey(o))) sc -= 15;
    if (R.rain_protection_required && !(ow && ow.waterproof)) sc -= 2; // parapluie ajouté ensuite
    if (!best || sc > best.sc) best = { o, sc };
  }
  const o = best ? best.o : { base_top: null, bottom: null, mid_layer: null, outerwear: null, shoes: null, accessories: [] };
  o.accessories = (candidates.accessory || []).filter((a) => a.score > 3).slice(0, 2).map((a) => a.id);
  return o;
}

let mode = 'llm';
let title = typeof parsed?.title === 'string' ? parsed.title.slice(0, 80) : null;
let advice = typeof parsed?.advice === 'string' ? parsed.advice : null;
let tips = Array.isArray(parsed?.tips) ? parsed.tips.filter((t) => typeof t === 'string').slice(0, 4) : [];
let palette = Array.isArray(parsed?.palette) ? parsed.palette.filter((t) => typeof t === 'string').slice(0, 4) : [];

// Réparations ciblées plutôt que tout jeter
const failed = Object.entries(llmChecks).filter(([, ok]) => !ok).map(([k]) => k);
if (parsed) {
  for (const cat of ['base_top', 'mid_layer', 'bottom', 'outerwear', 'shoes']) {
    if (outfit[cat] !== null && !itemOf(cat, outfit[cat])) { repairs.push(`pièce inconnue #${outfit[cat]} retirée`); outfit[cat] = null; }
  }
  const badAcc = outfit.accessories.filter((id) => !itemOf('accessories', id));
  if (badAcc.length) repairs.push(`accessoire(s) inconnu(s) retiré(s)`);
  outfit.accessories = [...new Set(outfit.accessories.filter((id) => itemOf('accessories', id)))];
  if (outfit.accessories.length > 3) { outfit.accessories = outfit.accessories.slice(0, 3); repairs.push('accessoires limités à 3'); }
  const need = { base_top: true, bottom: true, shoes: true, mid_layer: R.mid_layer_required, outerwear: R.outerwear_required };
  const chosenCount = ['base_top', 'bottom', 'shoes'].filter((c) => outfit[c] !== null).length;
  if (chosenCount >= 2) {  // le LLM a proposé une vraie tenue : on complète ce qui manque
    for (const [cat, required] of Object.entries(need)) {
      if (required && outfit[cat] === null && (candidates[cat] || []).length) {
        outfit[cat] = candidates[cat][0].id;
        repairs.push(`${cat} manquant ajouté (${candidates[cat][0].name})`);
      }
    }
  }
}
const usable = parsed && outfit.base_top !== null && outfit.bottom !== null && outfit.shoes !== null
  && (!R.mid_layer_required || outfit.mid_layer !== null) && (!R.outerwear_required || outfit.outerwear !== null);

if (!usable) {
  mode = 'fallback';
  outfit = bestDeterministic();
  if (apiError) warnings.push('Le modèle IA est indisponible : tenue proposée par l’algorithme de secours.');
  else warnings.push(`Réponse IA invalide (${failed.join(', ') || 'format'}) : tenue proposée par l’algorithme de secours.`);
  title = 'La sélection du jour';
  const names = ['base_top', 'mid_layer', 'bottom', 'outerwear', 'shoes']
    .map((c) => itemOf(c, outfit[c])?.name).filter(Boolean);
  advice = `Avec ${weather.description.toLowerCase()} et un ressenti de ${weather.effective_feel}°C à ${weather.city}, `
    + `je te propose : ${names.join(', ')}. Cette combinaison respecte ton style ${STYLE}, `
    + `évite tes tenues des derniers jours et reste adaptée à la température de la journée.`;
  tips = [];
  palette = [];
}

// ---------- 4. Réparations légères (tracées) ------------------------------
const finalOuter = itemOf('outerwear', outfit.outerwear);
const umbrella = (candidates.accessory || []).find((a) => a.subcategory === 'parapluie');
if (R.rain_protection_required && !(finalOuter && finalOuter.waterproof)
    && !outfit.accessories.some((id) => itemOf('accessories', id)?.subcategory === 'parapluie') && umbrella) {
  outfit.accessories = [...outfit.accessories.slice(0, 2), umbrella.id];
  repairs.push('parapluie ajouté');
}
// Anti-répétition GARANTIE : si la combinaison haut+bas a déjà été portée
// récemment, on remplace le bas (puis le haut) par le meilleur candidat libre.
if (base.forbidden_combos.includes(comboKey(outfit))) {
  const fixed = (() => {
    for (const b of candidates.bottom || []) {
      const o = { ...outfit, bottom: b.id };
      if (!base.forbidden_combos.includes(comboKey(o))) return { o, what: `bas remplacé par ${b.name}` };
    }
    for (const t of candidates.base_top || []) {
      const o = { ...outfit, base_top: t.id };
      if (!base.forbidden_combos.includes(comboKey(o))) return { o, what: `haut remplacé par ${t.name}` };
    }
    return null;
  })();
  if (fixed) { outfit = fixed.o; repairs.push(`combinaison déjà portée : ${fixed.what}`); warnings.push(`Ajustement anti-répétition : ${fixed.what}.`); }
}
if (weather.uv_high && !tips.some((t) => /crème|solaire|spf/i.test(t))) tips.push('UV élevés : pense à la crème solaire.');
if (R.layering_advised && !tips.some((t) => /couche|retirer|enlever/i.test(t))) {
  tips.push(`Écart de ${weather.swing}°C aujourd’hui : garde une couche facile à retirer.`);
}

// ---------- 5. Construction du résultat -----------------------------------
const finalItems = [];
for (const cat of ['base_top', 'mid_layer', 'bottom', 'outerwear', 'shoes']) {
  const it = itemOf(cat, outfit[cat]);
  if (it) finalItems.push({ category: cat, id: it.id, name: it.name, subcategory: it.subcategory, color: it.color, warmth: it.warmth, waterproof: it.waterproof, styles: it.styles });
}
for (const id of outfit.accessories) {
  const it = itemOf('accessories', id);
  if (it) finalItems.push({ category: 'accessory', id: it.id, name: it.name, subcategory: it.subcategory, color: it.color, warmth: it.warmth, waterproof: it.waterproof, styles: it.styles });
}
const finalChecks = runChecks(outfit, advice);

const savePayload = {
  user_id: req.user_id,
  outfit_date: req.outfit_date,
  source: req.source,
  style: STYLE,
  occasion: base.occasion,
  city: weather.city,
  weather,
  weather_band: weather.band,
  items: outfit,
  item_ids: finalItems.map((i) => i.id),
  combo_key: comboKey(outfit),
  title, advice,
  tips: { tips, palette, repairs, warnings, final_checks: finalChecks },
  generation_mode: mode,
  model: base.llm_request.model,
  llm_raw: (raw || apiError || '').slice(0, 4000),
  latency_ms: latency,
  checks: llmChecks,
  rule_score: ruleScore,
};

return {
  json: {
    req, weather, warnings,
    style: STYLE, occasion: base.occasion,
    outfit, items: finalItems, title, advice, tips, palette, repairs,
    generation_mode: mode, checks: llmChecks, final_checks: finalChecks, rule_score: ruleScore,
    latency_ms: latency, model: base.llm_request.model,
    save_payload: savePayload,
  },
};

// ============================================================
// Nœud : "Construire la réponse"   (Mode : Run Once for Each Item)
// Page HTML de la tenue (ou JSON si format=json, utilisé par l'évaluation).
// ============================================================
const v = $('Valider & évaluer la tenue').item.json;
const saved = $json.saved || {};
const outfitId = saved.outfit_id || null;
const { req, weather } = v;

if (req.format === 'json') {
  const body = {
    outfit_id: outfitId, outfit_date: req.outfit_date, source: req.source,
    style: v.style, occasion: v.occasion, title: v.title, advice: v.advice, tips: v.tips, palette: v.palette,
    items: v.items, weather, generation_mode: v.generation_mode, model: v.model,
    checks: v.checks, final_checks: v.final_checks, rule_score: v.rule_score,
    repairs: v.repairs, latency_ms: v.latency_ms, warnings: v.warnings,
  };
  return { json: { source: req.source, content_type: 'application/json; charset=utf-8', status_code: 200, response_body: JSON.stringify(body) } };
}

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const EMOJI = { base_top: '👕', mid_layer: '🧶', bottom: '👖', outerwear: '🧥', shoes: '👟', accessory: '🎒' };
const LABEL = { base_top: 'Haut', mid_layer: 'Couche', bottom: 'Bas', outerwear: 'Veste / manteau', shoes: 'Chaussures', accessory: 'Accessoire' };
const WX = (w) => (w.snow ? '❄️' : w.storm ? '⛈️' : w.rain ? '🌧️' : w.code <= 1 ? '☀️' : w.code <= 3 ? '⛅' : '🌫️');
const COLORS = { blanc: '#f5f5f5', noir: '#1f1f1f', gris: '#9ca3af', beige: '#d6c3a0', camel: '#c19a6b', marron: '#7b4a2e',
