  'bleu clair': '#9fb9d6', kaki: '#6b6b3a', vert: '#3f8f5a', 'vert olive': '#708238', rouge: '#c0392b', bordeaux: '#6d1a2b',
  jaune: '#f2c500', orange: '#e67e22', écru: '#efe8d8', crème: '#f3ead3', rose: '#e8a0b4', argent: '#c0c0c0' };
const swatch = (c) => COLORS[String(c).toLowerCase().trim()] || '#cbd5e1';
