const checksHtml = Object.entries(v.checks).map(([k, ok]) => `<span class="chk ${ok ? 'ok' : 'ko'}">${ok ? '✓' : '✗'} ${checkNames[k] || k}</span>`).join('');
const stars = outfitId && !req.source.startsWith('eval')
  ? [1, 2, 3, 4, 5].map((n) => `<a class="star" href="${base}outfit-feedback?id=${outfitId}&r=${n}">★<small>${n}</small></a>`).join('')
  : '<i>Simulation : notation désactivée</i>';

