${v.warnings.length ? `<div class="warn">${v.warnings.map(esc).join('<br>')}</div>` : ''}
<div class="card"><div class="grid">${itemsHtml}</div></div>
<div class="card"><div class="advice">${esc(v.advice)}</div>
${v.tips.length ? `<ul class="tips">${v.tips.map((t) => `<li>${esc(t)}</li>`).join('')}</ul>` : ''}
${v.palette.length ? `<div class="pal">${v.palette.map((c) => `<span><i style="background:${swatch(c)}"></i>${esc(c)}</span>`).join('')}</div>` : ''}
</div>
<div class="card"><b>Cette tenue te plaît ?</b><p style="margin:6px 0 10px;color:var(--mut);font-size:.9rem">Ta note ajuste les prochaines suggestions.</p><div class="stars">${stars}</div></div>
<div class="card"><b>Contrôle qualité automatique : ${Math.round(v.rule_score * 100)}%</b><div>${checksHtml}</div>
<div class="meta">Généré par ${v.generation_mode === 'llm' ? esc(v.model) : 'algorithme de secours'} en ${v.latency_ms} ms${v.repairs.length ? ' · corrections : ' + esc(v.repairs.join(', ')) : ''}${outfitId ? ' · tenue n°' + outfitId : ''}</div></div>
<p><a class="back" href="${base}dressing?user_id=${req.user_id}">← Retour au dressing</a></p>
</div>
<script>
async function laundry(id, btn){btn.disabled=true;
  try{const r=await fetch('${base}wardrobe-status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_id:id,status:'laundry'})});
  btn.textContent=r.ok?'✓':'!';}catch(e){btn.textContent='!';}}
</script></body></html>`;

return { json: { source: req.source, content_type: 'text/html; charset=utf-8', status_code: 200, response_body: html } };

// ============================================================
// Nœud : "Construire la réponse d'erreur"   (Mode : Run Once for Each Item)
// Erreur "métier" (utilisateur inconnu, garde-robe vide, météo HS...) :
// on répond proprement au lieu de laisser le webhook sans réponse.
// ============================================================
const req = $json.req || {};
const msg = $json.fatal || 'Erreur inconnue';
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

if (req.format === 'json') {
  return { json: { source: req.source || 'webhook', content_type: 'application/json; charset=utf-8', status_code: 422,
    response_body: JSON.stringify({ error: msg, warnings: $json.warnings || [] }) } };
}
const html = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Oups · Météo-Dressing</title><style>body{font-family:system-ui,sans-serif;background:#f6f4ef;display:grid;place-items:center;min-height:100vh;margin:0}
.c{background:#fff;padding:28px;border-radius:18px;max-width:460px;text-align:center;box-shadow:0 1px 3px rgba(0,0,0,.08)}a{color:#2f5d50}</style></head>
<body><div class="c"><div style="font-size:2.4rem">🧥❓</div><h2>Impossible de générer la tenue</h2><p>${esc(msg)}</p>
<p><a href="${esc(req.base_url || '')}dressing">← Retour au dressing</a></p></div></body></html>`;
return { json: { source: req.source || 'webhook', content_type: 'text/html; charset=utf-8', status_code: 422, response_body: html } };

// ============================================================
// Nœud : "Construire la page de l'appli"   (Mode : Run Once for Each Item)
// Mini-interface web servie directement par n8n (GET /webhook/dressing) :
// formulaire (style, occasion, ville, demain, simulation), historique,
// indicateurs d'évaluation en direct et linge sale.
// ============================================================
const q = $json.q || {};
const d = $json.data || {};
const base = q.base_url || '';
const users = d.users || [];
const me = users.find((u) => u.id === q.user_id) || users[0] || { id: 1, name: '?', city: 'Paris', style: 'casual' };
const S = d.summary || {};
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const opt = (vals, sel) => vals.map(([v, l]) => `<option value="${v}" ${v === sel ? 'selected' : ''}>${l}</option>`).join('');

const STYLES = [['casual', 'Casual'], ['chic', 'Chic'], ['business', 'Business'], ['streetwear', 'Streetwear'], ['sport', 'Sport'], ['boheme', 'Bohème']];
const OCC = [['quotidien', 'Quotidien'], ['travail', 'Travail'], ['sortie', 'Sortie'], ['rendez-vous', 'Rendez-vous'], ['week-end', 'Week-end'], ['sport', 'Sport'], ['voyage', 'Voyage']];
const SIM = [['', 'Météo réelle (Open-Meteo)'], ['pluie_froide', '🌧️ Simuler : pluie froide'], ['canicule', '🔥 Simuler : canicule'],
  ['neige', '❄️ Simuler : neige'], ['vent_fort', '💨 Simuler : vent fort'], ['printemps', '🌸 Simuler : printemps']];
const BAND = { very_cold: '🥶', cold: '❄️', cool: '🍂', mild: '🌤️', warm: '☀️', hot: '🔥' };

const rows = (d.recent || []).map((r) => `<tr><td>${esc(r.outfit_date)}</td><td>${BAND[r.band] || ''} <b>${esc(r.title)}</b><br><small>${esc((r.items || []).join(' · '))}</small></td>
  <td>${esc(r.style)}</td><td>${r.mode === 'llm' ? '🤖' : '⚙️'} ${r.score !== null ? Math.round(r.score * 100) + '%' : '–'}</td>
  <td>${r.rating ? '★'.repeat(r.rating) : [1, 2, 3, 4, 5].map((n) => `<a href="${base}outfit-feedback?id=${r.id}&r=${n}" title="${n}/5">☆</a>`).join('')}</td></tr>`).join('');
const laundry = (d.laundry || []).map((i) => `<li>${esc(i.name)} <button onclick="clean(${i.id},this)">Propre ✓</button></li>`).join('');

const html = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Météo-Dressing</title><style>
:root{--bg:#f6f4ef;--ink:#1d1b16;--mut:#6b675e;--acc:#2f5d50}
*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink)}
.wrap{max-width:900px;margin:0 auto;padding:24px 16px 60px}h1{margin:0}header p{color:var(--mut);margin:4px 0 18px}
.card{background:#fff;border-radius:18px;padding:20px;margin-bottom:16px;box-shadow:0 1px 3px rgba(0,0,0,.06)}
form{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px}
label{display:flex;flex-direction:column;font-size:.8rem;color:var(--mut);gap:4px}
select,input{font:inherit;padding:10px;border:1px solid #ddd;border-radius:10px;background:#fff;color:var(--ink)}
button.go{grid-column:1/-1;font:inherit;font-weight:600;padding:14px;border:0;border-radius:12px;background:var(--acc);color:#fff;cursor:pointer}
.kpis{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}
.kpi{background:#f1efe9;border-radius:14px;padding:12px}.kpi b{font-size:1.4rem;display:block}.kpi small{color:var(--mut)}
table{width:100%;border-collapse:collapse;font-size:.9rem}td,th{padding:8px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}
td small{color:var(--mut)}td a{text-decoration:none;color:#e0a100;font-size:1.1rem}.scroll{overflow-x:auto}
#load{display:none;text-align:center;padding:30px;font-size:1.1rem}
ul{padding-left:18px}li button{font-size:.75rem;margin-left:6px;border:0;background:#e3f4ea;border-radius:8px;padding:3px 8px;cursor:pointer}
</style></head><body><div class="wrap">
<header><h1>👗 Météo-Dressing</h1><p>Ta tenue du jour selon la météo, ton style et ce que tu as déjà porté.</p></header>
<div class="card" id="formcard"><form id="f">
  <label>Profil<select name="user_id" onchange="location.href='${base}dressing?user_id='+this.value">${opt(users.map((u) => [String(u.id), `${esc(u.name)} (${esc(u.city)})`]), String(me.id))}</select></label>
  <label>Ville<input name="city" placeholder="${esc(me.city)}"></label>
  <label>Style<select name="style">${opt(STYLES, me.style)}</select></label>
  <label>Occasion<select name="occasion">${opt(OCC, 'quotidien')}</select></label>
  <label>Pour<select name="day_offset"><option value="0">Aujourd'hui</option><option value="1">Demain</option></select></label>
  <label>Météo<select name="simulate">${opt(SIM, '')}</select></label>
  <button class="go" type="submit">✨ Générer ma tenue</button>
</form></div>
<div id="load" class="card">🧵 Ton styliste IA consulte la météo et ta garde-robe…</div>
<div class="card"><b>Qualité du système (tous les runs)</b><div class="kpis" style="margin-top:10px">
  <div class="kpi"><b>${S.total_runs ?? 0}</b><small>tenues générées</small></div>
  <div class="kpi"><b>${S.avg_rule_score_pct ?? '–'}%</b><small>score contrôles auto</small></div>
  <div class="kpi"><b>${S.llm_success_pct ?? '–'}%</b><small>sorties IA utilisables</small></div>
  <div class="kpi"><b>${S.avg_user_rating ?? '–'}/5</b><small>note moyenne (${S.rated_outfits ?? 0} avis)</small></div>
  <div class="kpi"><b>${S.avg_latency_ms ?? '–'} ms</b><small>latence moyenne</small></div>
</div></div>
<div class="card"><b>7 dernières tenues de ${esc(me.name)}</b><div class="scroll"><table><tr><th>Date</th><th>Tenue</th><th>Style</th><th>Qualité</th><th>Note</th></tr>
${rows || '<tr><td colspan="5"><i>Aucune tenue pour le moment.</i></td></tr>'}</table></div></div>
<div class="card"><b>🧺 Au linge sale</b>${laundry ? `<ul>${laundry}</ul>` : '<p style="color:var(--mut)">Rien au sale 🎉</p>'}</div>
</div>
<script>
document.getElementById('f').addEventListener('submit', async (e) => {
  e.preventDefault();
  const fd = Object.fromEntries(new FormData(e.target));
  const body = { user_id: Number(fd.user_id), style: fd.style, occasion: fd.occasion, day_offset: Number(fd.day_offset), format: 'html' };
  if (fd.city.trim()) body.city = fd.city.trim();
  if (fd.simulate) body.simulate = fd.simulate;
  document.getElementById('load').style.display = 'block';
  try {
    const r = await fetch('${base}outfit', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    const html = await r.text(); document.open(); document.write(html); document.close();
  } catch (err) { document.getElementById('load').textContent = 'Erreur réseau : ' + err.message; }
});
async function clean(id, btn){ btn.disabled = true;
  const r = await fetch('${base}wardrobe-status', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ item_id:id, status:'available' }) });
  btn.textContent = r.ok ? 'OK' : 'Erreur'; }
</script></body></html>`;

return { json: { source: 'webhook', content_type: 'text/html; charset=utf-8', status_code: 200, response_body: html } };

// ============================================================
// Nœud : "Construire la page merci"   (Mode : Run Once for Each Item)
// Après un clic sur une étoile : la note est enregistrée (rate_outfit)
// et sert à la fois d'évaluation humaine ET d'apprentissage des goûts.
// ============================================================
const res = $json.res || {};
const q = $json.q || {};
const base = q.base_url || '';
const ok = res.ok === true;
const html = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Merci · Météo-Dressing</title><style>body{font-family:system-ui,sans-serif;background:#f6f4ef;display:grid;place-items:center;min-height:100vh;margin:0}
.c{background:#fff;padding:28px;border-radius:18px;max-width:420px;text-align:center;box-shadow:0 1px 3px rgba(0,0,0,.08)}a{color:#2f5d50}</style></head>
<body><div class="c"><div style="font-size:2.4rem">${ok ? '⭐'.repeat(res.rating) : '⚠️'}</div>
<h2>${ok ? 'Merci pour ta note !' : 'Note non enregistrée'}</h2>
<p>${ok ? 'Les prochaines suggestions tiendront compte de ton avis.' : String(res.error || 'Paramètres invalides').replace(/</g, '&lt;')}</p>
<p><a href="${base}dressing">← Retour au dressing</a></p></div></body></html>`;
return { json: { source: 'webhook', content_type: 'text/html; charset=utf-8', status_code: ok ? 200 : 400, response_body: html } };

// ============================================================
// Nœud : "Réponse statut pièce"   (Mode : Run Once for Each Item)
// ============================================================
const res = $json.res;
return { json: { source: 'webhook', content_type: 'application/json; charset=utf-8',
  status_code: res ? 200 : 404,
  response_body: JSON.stringify(res ? { ok: true, item: res } : { ok: false, error: 'Pièce introuvable' }) } };
